-- 2223 🏋️ Exercises from the book "scanning-how-to-train-it-and-develop-game-awareness-see-more-think-quicker-play-" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'scanning-how-to-train-it-and-develop-game-awareness-see-more-think-quicker-play-');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Juego de Posicion 4v4+3 with visual cues', 'possession', 'overload', 'in_possession', 18, 19, 'Example: Pep Guardiola''s ''Juego de Posicion'' 4v4 (+3) Game', 'Guardiola (Man City)', 'Keep the ball against a counter-pressing four with joker support, while scanning to spot team-mates'' colour cues before receiving.', '10 x 15 yard box. Four blues stand on the long sides (two each side), four reds start inside, one yellow joker at each end and one joker in the middle.', 'Coach serves to the blues, who keep the ball with the three jokers while the reds press as a unit to close passing angles. When the reds win it the teams swap: blues come inside and counter-press, reds go to the outside and keep it with the jokers.', 'Jokers always play for the side in possession; the middle joker can be challenged.', 'eyeQ layer (2 progressions): an end player raises a coloured cone/glove when the opposite end player receives, and the player receiving from an end must call the colour before his touch; a player receiving from the middle joker, or an end player receiving from a side player, must spot and call the colour shown by the player on the opposite side.', 'Open body shape when receiving from a neutral end player so you can see forward; look away from the ball as it travels to the trigger player; split attention between cues, ball and opponents.', '4v4+3', 11, 11, '10 x 15 yards', 13.7, 9.1, NULL, false, false, false, NULL, 10),
  ('6v3 to sliders with colour call-out', 'positional_game', 'overload', 'in_possession', 27, 27, 'Dundee Utd Soccer eyeQ Scanning Practice Example', 'Kevin McGreskin with Jackie McNamara (Partick Thistle / Dundee United)', 'Keep possession and find an outside ''slider'' while scanning across the area to read a visual cue, promoting open body shape in an opposed game.', '36 x 30 yard area with two mini goals behind one end line. Six oranges and three whites inside; four sliders (outside neutral players) move along the four sides.', 'Oranges score by passing to a slider and receiving it back after keeping the ball inside; whites try to win it and score in either mini goal. In the eyeQ version, when a slider gets the ball the slider opposite holds up a red or yellow cue and the orange receiving from the slider must call that colour after the pass and before his first touch.', 'At least one pass inside the area before playing to a slider; a point only counts when the receiver calls the correct colour (eyeQ version).', 'Full description, coaching points and further progressions given later in the book (p163).', 'Scan across to the opposite slider while the ball travels; get side-on so both the passer and the far side are visible.', '6v3+4', 13, 13, '36 x 30 yards', 32.9, 27.4, NULL, true, false, true, NULL, 20),
  ('Pass to opposite colour with flashers', 'passing_unopposed', 'unopposed', 'in_possession', 115, 123, 'Practice Example: Pass to Opposite Colour in a Basic Awareness Practice (+ Progressions 1-3)', 'Kevin McGreskin (Soccer eyeQ)', 'Builds the habit of scanning before receiving and an open body shape to the passer, then more and more reference points to track.', 'Rectangle from 20x30 up to 40x60 yards; two teams of 6-8 mixed together inside with 3-4 balls.', 'Players move freely and may only pass to someone in the other colour; extra balls raise the tempo. The coach watches who looks before the ball arrives versus who only looks after receiving.', 'Pass only to the opposite colour; from Progression 1 the receiver must shout the colour of the visual cue after the pass is made and before his first touch.', 'P1: one team flasher per team (white and blue) moves along the outside holding up a red or yellow cue (glove/cone) that teammates must spot and call. P2: red and yellow balls, and the two outside flashers are colour-coded to the balls - receiving a red ball means calling the red flasher''s cue. P3: add a white ball and bring back the team flashers too - on receiving the white ball you call your team flasher''s cue, pass to him and swap roles (drop out on a different side), the flasher dribbling in.', 'Active scanning; open body to passer and flasher; confirm with a last look after the pass and before the first touch; pass to the back foot/open side; follow-on - re-scan straight after passing; praise early looks but demand the final check.', '2 teams of 6-8 (+2 to 4 outside flashers)', 12, 20, '20 x 30 up to 40 x 60 yards', 54.9, 36.6, NULL, false, false, false, NULL, 30),
  ('Ajax Square with visual cues', 'passing_unopposed', 'unopposed', 'in_possession', 124, 127, 'Drill Example: Basic ''Ajax Square'' Passing Drill - Pass and Follow (+ Progressions 1-3)', 'Kevin McGreskin (Soccer eyeQ)', 'Layers scanning and quick off-ball concentration onto a standard pass-and-follow square drill.', 'Two interlocking squares with cone stations A-D on each corner, players queued at A; the overlap creates traffic along two sides.', 'Pass round the square and follow your pass, control then pass (2 touches). Progressions make the next player in the sequence hold up a red or yellow cue for the receiver to spot and shout before his touch.', '2 touches - control and pass, follow your pass; tight touch that stays playable.', 'P1: next player holds up a visual cue for the receiver to call. P2: yellow = carry on the same way, red = reverse the direction of play. P3: both colours held up (''orange'') = play a diagonal across the square back to the start; when receiving the diagonal you choose the direction.', 'Quality of pass (line/pace), timing and speed of movement off the cone, tight first touch, working both feet and both directions; keep demanding technique as the mental load rises.', 'group of about 8-10 per double square', 8, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 40),
  ('Sequence passing with cues and grid zones', 'passing_unopposed', 'unopposed', 'in_possession', 132, 149, 'Level 2 Practice Example 1: Vision and Awareness Sequence Passing Practice (+ Progressions 1-6)', 'Kevin McGreskin (Soccer eyeQ)', 'Develops pre-scanning and adaptive positioning relative to several teammates and ''opponents'' within a numbered passing sequence.', 'Square from 24x24 up to 42x42 yards; two teams of 5-7, one ball per team, each player numbered; later the grid is split into 3 columns and 3 rows.', 'Both teams move about the area passing in number order (1-2-3-4-5-1). Progressions add visual cues held by the player after the receiver, column/row restrictions, tennis balls thrown in a second sequence, floating players to avoid and floaters who can demand the ball.', 'Pass in sequence; from P1 call the next player''s cue after the pass and before the first touch; from P2 you may not receive while in the same column or row as your passer.', 'P1: next player holds up a red/yellow cue for the receiver to call. P2: 3x3 grid, cannot receive in the passer''s column or row. P3: 2 tennis balls per team thrown in their own order (e.g. 2-4-1-3-5-2) to a free teammate while the football goes 1-5 - only thrown when receiving the football, before the first touch. P4: column/row rule now applies to tennis balls too. P5: 4 floaters (2 green, 2 yellow) roam; blues may not receive in a square with a yellow, whites not with a green (extra option: the same for tennis balls). P6: two colour-coded flashers outside; floaters can shout for the football and must get it, then pass to the other floater, and the next player in the sequence spots the flasher''s cue and moves to receive; option - floaters can demand from either team.', 'Know where your passer and next receiver are before the ball comes; open to both; check again after the pass; pass into the space in front of the open body, back foot; re-scan straight away to support; small position adjustments of a yard or two; demand accurate throws.', '2 teams of 5-7 (+4 floaters, +2 flashers in later progressions)', 10, 20, '24 x 24 up to 42 x 42 yards', 38.4, 38.4, NULL, false, false, false, NULL, 50),
  ('Opposite colour passing with tagging jokers', 'passing_opposed', 'passive', 'in_possession', 150, 154, 'Level 2 Practice Example 2: Pass to Opposite Colour with Team Flashers (+ Progressions 1-2)', 'Kevin McGreskin (Soccer eyeQ)', 'Adds positioning away from opponents and third-man support to the opposite-colour scanning practice.', 'Same mixed two-team area as the Level 1 opposite-colour practice with a team flasher outside for each team; later 3 jokers inside and 3 tennis balls per team.', 'Pass only to the other colour, calling your team flasher''s cue before the first touch. Jokers then try to tag the receiver while the ball is travelling; in P2 the receiver also throws a tennis ball to a free teammate of the same colour, and the football may only go to a player holding a tennis ball.', 'Tag only between the pass and the receiver''s first touch; tagged player does a forfeit (push-up/burpee); 90-second rounds with a joker target (e.g. 6 tags) deciding who does the forfeit; release within 4-5 seconds or the jokers score; swap jokers and flashers each round.', 'P1: 3 jokers who tag receivers. P2: 3 tennis balls per team thrown to a free teammate, football only to a tennis-ball holder. Option: jokers can also tag players receiving a tennis ball.', 'Scan for flasher and jokers; pass only to a player in space; open body to passer, flasher and next target; first touch beats calling the colour when about to be tagged - keep possession; move to support a tennis-ball holder straight after passing.', '2 teams of 6-8 + 2 flashers + 3 jokers', 15, 21, NULL, NULL, NULL, NULL, false, false, false, NULL, 60),
  ('6v3 with four outside sliders', 'possession', 'overload', 'in_possession', 160, 162, 'Level 3 Practice Example 1: Opposed 6v3 (+4) Vision and Awareness Practice', 'Kevin McGreskin (Soccer eyeQ)', 'Raises concentration and scanning under real pressure, especially for the outside support players.', '30 x 36 yards; 6 blues v 3 reds inside, 4 sliders outside (2 yellow on opposite sides, 2 green on the other two) moving along their line; 2 mini goals behind one end for the reds.', 'Blues score a point by passing to a slider and getting it back; they need at least one pass inside before scoring again. Reds who win it attack either mini goal.', 'Point = slider plays it back in; at least 1 inside pass between points; sliders free touches but only 1 touch if no inside pass has been made yet; can use goals in corners or up to 4 goals for the reds.', 'Book''s Progressions 1-3 begin on p163 (outside this range).', 'Sliders know where teammates are before receiving and control the tempo; inside players open to as much of the area as possible, look up field; pick the teammate with most time and space; support and scan after passing.', '6v3 + 4 outside', 13, 13, '30 x 36 yards', 32.9, 27.4, NULL, true, false, false, NULL, 70),
  ('6v3 awareness game with four cone gates', 'positional_game', 'overload', 'in_possession', 171, 176, 'Practice Example 2: Awareness Game (6v3) with 4 Cone Gates', NULL, 'Build scanning, open body shape and switching play to free gates under pressure.', 'Square area with 4 small cone gates spread inside; 6 blue attackers v 3 red defenders, coach with balls on the side.', 'Blues keep the ball and score by passing to a team-mate through any gate. Reds press to win it and score by dribbling out of the area alone or combining.', 'Goal = completed pass through a gate to a team-mate; reds score by dribbling out of the grid.', 'P1: each gate a different colour with 4 matching coloured flashers moving round the outside; the flasher matching the gate shows red/yellow just before the pass and the receiver must call it before his first touch for the goal to count; reds now score by passing to any flasher (var 1: reds keep the ball and score per pass to a flasher; var 2: bonus if receiver finds the flasher within 2 touches). P2: blues carry 3 tennis balls; receiver through the gate must hold a tennis ball, call the colour and throw the tennis ball to a free team-mate (var: 1 pt without throw, 3 with).', 'Know where ball, team-mates and opponents are; open body to passer and next action; check again before first touch; pre-scan for the right flasher as play builds; re-engage scanning after passing.', '6v3 (+4 flashers in progressions)', 9, 13, NULL, NULL, NULL, NULL, false, false, true, NULL, 80),
  ('6(+2)v3 bounce off floaters game', 'possession', 'overload', 'in_possession', 177, 182, 'Practice Example 3: 6 (+2) v 3 Pass to Floating Players Game', NULL, 'Quick one-touch combinations off floaters while scanning away from the ball.', 'Square area; 6 blues and 2 floaters (one green, one yellow) inside v 3 reds; coach serves from the side.', 'Blues score by passing into a floater and getting the ball back from him (to any blue). Reds press and score by dribbling out of the area.', 'Point = pass to floater and return; if reds just man-mark the floaters, 10 passes also scores.', 'P1: add a green and a yellow flasher outside; the flasher matching the floater shows a colour when that floater receives and the blue receiving from the floater must call it before his first touch; reds score by passing to a flasher (var 1: reds keep it and score per pass to a flasher; var 2: bonus if blues reach the flasher within 2-3 touches of the floater''s pass); flasher/floater pairs may swap if floaters are man-marked. P2: blues carry 3 tennis balls; receiver from a floater must hold a tennis ball, call the colour and throw it to a free team-mate (var: 1 pt without throw, 3 with).', 'Floaters scan off the ball and play one touch often; build a picture away from the ball; open body; last look before first touch.', '6(+2)v3', 11, 13, NULL, NULL, NULL, NULL, false, false, false, NULL, 90),
  ('Liverpool 5v2 rondo with magic player', 'rondo', 'overload', 'in_possession', 187, 188, 'Rondo Example: Liverpool Rondo with "Magic Player"', 'Klopp (Liverpool)', 'Keep the ball in a tight rondo using a free-moving extra player, adding scanning beyond the grid.', 'Groups of 7 in 10 yard squares (several grids side by side); 4 reds on the outside, 1 red magic player free inside or out, 2 yellow defenders.', 'Reds aim for 15 consecutive passes while the 2 defenders work together to close angles and win it. A player who loses the ball before 15 passes swaps with the defender who won it.', 'Outside players 2 touches; magic player unlimited touches; 15 passes = point.', 'eyeQ: a flasher circulates round the whole set of grids; whoever receives from the magic player calls the colour shown (bonus point); if the defenders win it they score by passing to the flasher.', 'Lift the head to see the bigger picture; take quick snapshots of team-mates; split attention away from the ball.', '5v2 per group of 7', 7, NULL, '10 x 10 yards', 9.1, 9.1, NULL, false, false, false, NULL, 100),
  ('Passing Y drill with lay-off', 'passing_unopposed', 'unopposed', 'in_possession', 189, 191, 'Passing Drill Example 1: Passing "Y" Drill', NULL, 'Pass, lay-off and timed runs in a Y pattern, with added scanning.', '5 players A-E in a Y: A at the base, B in the middle, C and E at the two top ends, D waiting next at the base.', 'A to B, B lays back for A stepping on, A plays diagonal to C, C plays short for B''s movement, B returns the other way for C to run onto, C gives to the next player D; repeat on the right side with E. Players follow their pass.', 'Progress to 1 touch.', 'P1: end player C shows a colour after A''s pass and B must call it before his first touch. P2: also end player E flashes as A hits the pass to C and C must call it before receiving.', 'Weight the lay-off so A can take it on the move; time runs; use both feet; communicate with heads up.', '5', 5, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 110),
  ('Short and long passing circuit', 'passing_unopposed', 'unopposed', 'in_possession', 192, 193, 'Passing Drill Example 2: Short and Long Passing Circuit', NULL, 'Mix of long diagonals and short lay-offs with checking away to receive.', '7 players A-G at cones: A and G at the bottom, B and C on the left, D at the top, E and F on the right.', 'A diagonal to B, B lays off to C, C diagonal to D, D diagonal to E, E lays off to F, F plays to the next waiting player G; everyone moves on to the next station after passing.', NULL, 'eyeQ: each receiver must call the colour held up by the player on the opposite, same-colour cone (blue, red, white cones) before taking the ball.', 'Inside foot for short passes; check away before moving to receive so 1 touch is possible.', '7', 7, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 120),
  ('Dynamic passing double square', 'passing_unopposed', 'unopposed', 'in_possession', 194, 195, 'Passing Drill Example 3: Dynamic Passing Double Square', NULL, 'One-touch passing, third-man combinations and timing of support runs.', '25 yard square with a smaller square marked in the middle; 6 outside players (reds and blues) at the corners and 3 white inside players.', 'Outside player passes into an inside player, a team-mate moves into the centre grid and times his run to receive the lay-off and play the ball out to the next corner; continuous clockwise. Outside players follow their pass, inside players rotate anticlockwise.', NULL, 'Reverse direction for both feet; change inside players often. eyeQ: outside players call the colour shown by the next outside player to their left, inside players call the colour shown by the next inside player.', 'Rhythm: pass in, move into the grid, time the run to play out.', '9 (6 outside + 3 inside)', 9, NULL, '25 x 25 yards', 22.9, 22.9, NULL, false, false, false, NULL, 130),
  ('Pocket box possession to target players', 'positional_game', 'overload', 'in_possession', 196, 198, 'Possession Game Example 1: Pocket Box Possession Game', NULL, 'Keep possession and find a target player stepping into an end zone pocket.', 'Area sized to age/level with 2 end zones; 6 blues v 3 reds inside, 2 target players outside the area, coach serving.', 'Blues keep the ball from the coach''s pass while tracking the target players. When a target steps into an end zone blues must find him within 5 seconds to score. Reds press and score by passing to either target.', 'Pass to target within 5 seconds of him entering the zone = goal.', 'P1: the opposite target shows a colour when the other target receives; the blue receiving from the target calls it (bonus point if he can then pass to that target). P2: targets join the blue team and rotate into the area after receiving.', 'Scan up the pitch for the target; open body; last look before first touch.', '6v3 + 2 target players', 11, 11, NULL, NULL, NULL, NULL, false, false, true, NULL, 140),
  ('End to end three zone possession', 'positional_game', 'overload', 'in_possession', 199, 202, 'Possession Game Example 2: End to End 3 Zone Possession Game', NULL, 'Transfer the ball between end zones through middle jokers.', 'Two larger end zones and a narrow middle zone; 3 blues and 1 red in each end zone, 2 jokers and 1 red in the middle; coach serves.', 'Coach starts a 3v1 in one end zone; blues pass into a middle joker who plays to the blues in the far end. The red in that zone tries to win it and dribble over the end line (middle red may help); middle red blocks passes to the jokers.', 'Rotate the 3 defenders often.', 'P1: a blue in the far zone shows a colour when a joker receives; the joker must call it. P2: all 3 far-zone players show a colour; joker calls the odd one out and gets a bonus for passing to him; if all 3 show the same colour he must play back into the first zone.', 'Jokers take early looks at the far zone and open up; last look before receiving.', '6(+2)v3', 11, 11, NULL, NULL, NULL, NULL, false, false, true, NULL, 150),
  ('6v4 plus six outside support players', 'possession', 'overload', 'in_possession', 203, 205, 'Possession Game Example 3: 6v4 +6 Outside Support Players', NULL, 'Keep the ball using outside support and get it back from them.', 'Area sized to age/level; 6 blues v 4 reds inside, 6 white support players around the outside; coach serves.', 'Blues keep possession and score by passing to an outside player and receiving it back. Reds press and score by dribbling out (or into 2-4 mini goals around the area).', NULL, 'P1: support players colour-coded in opposite pairs; when one receives, his opposite flashes a colour and the blue receiving back must call it. P2: after passing back in, a support player swaps with one next to him so flashers keep moving.', 'Early looks for the flasher; open body; last look before first touch; read pressure.', '6v4 + 6', 16, 16, NULL, NULL, NULL, NULL, false, false, false, NULL, 160),
  ('3v3 scan and play forward bounce game', 'small_sided_game', 'opposed', 'in_possession', 206, 209, 'Small Sided Game Example 1: Scan to Play Forward Bounce Game', NULL, 'Play forward early using bounce players and support the attack.', 'Pitch with halfway line and 2 goals with GKs; 3v3 inside, each team with 4 outside bounce players: one each side of its own half and one each side of the goal it attacks.', 'Play starts from a GK; both teams use their bounce players to keep it, recycle and build, and the end bounce players set up chances.', 'One-touch finish from an end bounce player''s pass = 2 goals.', 'P1: when a side support player receives, the end bounce player on the opposite side flashes and the receiver calls it before his first touch. P2: when a side player receives, the bounce player on the same side flashes and the end bounce player receiving must call it. Rule variations: miss the call = possession to the other GK; limit 1-2 touches; unlimited touches; bonus goal for passing to the flasher within 2 touches.', 'Play forward early when on and join the attack quickly.', '3v3 + 2 GKs + 8 bounce players', 16, 16, NULL, NULL, NULL, NULL, true, true, true, NULL, 170),
  ('3v3 play to advanced wide players', 'small_sided_game', 'opposed', 'in_possession', 210, 212, 'Small Sided Game Example 2: Play to Advanced Wide Players Game', NULL, 'Get the ball wide to advanced outside players to cross, with supporting runs to score.', 'Pitch with 2 goals and GKs; 3v3 inside, each team has 2 outside players restricted to wide channels high up the pitch marked by cones.', 'Starts from a GK; team in possession tries to get the ball wide so the outside players cross while team-mates make runs; outside players may also combine or recycle. Keep possession if no chance is on.', NULL, 'eyeQ: when one outside player receives, the one on the opposite side flashes and anyone receiving back from him must call it. Rule variations: miss = possession to the other GK; 1-2 touch limit; unlimited touches; bonus goal for reaching the flasher within 2 touches.', NULL, '3v3 + 2 GKs + 4 outside', 12, 12, NULL, NULL, NULL, NULL, true, true, true, NULL, 180)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'scanning-how-to-train-it-and-develop-game-awareness-see-more-think-quicker-play-') b;
INSERT INTO schema_migrations (filename) VALUES ('2223-exercises-book-scanning-how-to-train-it-and-develop-game-awareness-see-more.sql') ON CONFLICT DO NOTHING;
COMMIT;
